import heapq


def _ledger(sequence_first, original_tax):
    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            if sequence_first:
                rank = (sequence, event.get("revision", 0), position)
            else:
                rank = (event.get("revision", 0), position)
            if event_id not in chosen or rank > chosen[event_id][0]:
                chosen[event_id] = (rank, event)

        balances = dict(data.get("opening", {}))
        half_up = data["rounding"] == "half_up"

        def rounded(numerator):
            return (numerator + 5000) // 10000 if half_up else numerator // 10000

        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount))
            base = raw if original_tax else net
            total = net + rounded(base * event.get("tax_bp", 0))
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _component_06():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        rows = {name: {row["version"]: row for row in packages[name]} for name in names}
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        choices = [[-1] + list(rows[name]) for name in names]
        best_key = None
        best = None

        for values in product(*choices):
            installed = dict(zip(names, values))
            if any(installed.get(name, -1) < low or installed.get(name, -1) > high
                   for name, (low, high) in roots.items()):
                continue
            if any(version != -1 and version in blocked.get(name, [])
                   for name, version in installed.items()):
                continue
            if any(version != -1 and name in pins and version != pins[name]
                   for name, version in installed.items()):
                continue

            closure = set()
            edges = {}
            pending = list(roots)
            valid = True
            while pending and valid:
                name = pending.pop()
                if name in closure:
                    continue
                version = installed.get(name, -1)
                if version == -1 or version not in rows.get(name, {}):
                    valid = False
                    break
                closure.add(name)
                edges[name] = []
                for dep in rows[name][version].get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    target_version = installed.get(target, -1)
                    if not dep["min"] <= target_version <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(target)
                    pending.append(target)

            if not valid or {name for name, version in installed.items() if version != -1} != closure:
                continue

            active, finished = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(target) for target in edges.get(name, [])):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            if not all(visit(name) for name in closure):
                continue

            key = tuple(installed[name] for name in sorted(names, reverse=True))
            if best_key is None or key < best_key:
                best_key = key
                best = {name: version for name, version in installed.items() if version != -1}

        return {"error": "unsatisfiable"} if best is None else {"versions": best}
    return solve


def _component_07():
    def solve(data):
        jobs = [job for job in data["jobs"]
                if job["id"] not in set(data.get("blocked", []))]
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        k = data["k"]
        best_value = None
        best_ids = None

        for mask in range(1 << len(jobs)):
            selected = [jobs[i] for i in range(len(jobs)) if mask & (1 << i)]
            if len(selected) != k:
                continue
            ids = tuple(sorted(job["id"] for job in selected))
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in selected:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered = sorted(selected, key=lambda job: (job["start"], job["end"]))
            if any(ordered[i]["end"] > ordered[i + 1]["start"]
                   for i in range(len(ordered) - 1)):
                continue
            value = sum(job["value"] for job in selected)
            if (best_value is None or value > best_value or
                    (value == best_value and ids > best_ids)):
                best_value, best_ids = value, ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _component_08():
    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        source = data["source"]
        start_mask = bit.get(source, 0)
        wanted = data["coupons"]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start_state = (source, start_mask, 0)
        distance = {start_state: data["start"]}
        queue = [(data["start"], source, start_mask, 0)]
        while queue:
            time, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if distance.get(state) != time:
                continue
            if node == data["target"] and mask == full and used == wanted:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], used)]
                if used < wanted:
                    duration = max(1, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, used + 1))
                for duration, next_used in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | bit.get(next_node, 0)
                    next_state = (next_node, next_mask, next_used)
                    if arrival < distance.get(next_state, float("inf")):
                        distance[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask, next_used))
        return {"arrival": None}
    return solve


